<style>
    body {
        font-family: "Times New Roman", Times, serif;
        background-color: #fdfbf7;
        color: #111;
        margin: 20px auto;
        padding: 20px;
        max-width: 1000px;
        font-size: 11px;
        line-height: 1.25;
    }

    /* Top Header */
    .header {
        border-bottom: 3px double #000;
        padding-bottom: 5px;
        margin-bottom: 10px;
        display: flex;
        justify-content: space-between;
        align-items: baseline;
        font-weight: bold;
    }
    .header .title {
        font-size: 18px;
        letter-spacing: 2px;
        text-align: center;
    }

    /* Column Layout */
    .container {
        display: grid;
        grid-template-columns: 1fr 1fr 1fr;
        gap: 15px;
    }

    .column {
        border-right: 1px solid #777;
        padding-right: 12px;
    }
    .column:last-child {
        border-right: none;
        padding-right: 0;
    }

    /* Headings */
    h2 {
        font-size: 11px;
        text-align: center;
        margin: 8px 0 4px 0;
        text-transform: uppercase;
        font-weight: bold;
    }
    h3 {
        font-size: 12px;
        text-align: center;
        margin: 10px 0 5px 0;
        letter-spacing: 1px;
    }

    p {
        margin: 0 0 6px 0;
        text-align: justify;
        text-indent: 10px;
    }

    .no-indent {
        text-indent: 0;
    }

    .italic {
        font-style: italic;
    }

    .bold {
        font-weight: bold;
    }

    .center {
        text-align: center;
        text-indent: 0;
    }

    /* Dot leaders / Tables */
    .data-line {
        display: flex;
        justify-content: space-between;
        margin-bottom: 2px;
    }
    .dots {
        flex-grow: 1;
        border-bottom: 1px dotted #444;
        margin: 0 5px 3px 5px;
    }

    .table-rate {
        width: 100%;
        margin: 5px 0;
        border-collapse: collapse;
    }
    .table-rate td {
        padding: 1px 2px;
    }

    /* Rotated Header Table (Hospedaria de Immigrantes) */
    .immigrant-box {
        border: 1px solid #000;
        padding: 4px;
        margin: 10px 0;
    }

    .upside-down-header {
        transform: rotate(180deg);
        writing-mode: vertical-rl;
        text-align: right;
        font-size: 9px;
        white-space: nowrap;
    }

    .table-immigrant {
        width: 100%;
        border-collapse: collapse;
